mapper.select:
SELECT 
FROM ActivityTreasureHunt a left join GoodsSku sku on a.skuId = sku.id
WHERE a.ID = #{id}

SELECT

FROM ActivityTreasureHunt a left join GoodsSku sku on a.skuId = sku.id
WHERE 1 = 1

    AND a.id = #{id}


    AND a.activityName LIKE CONCAT('%',#{activityName}, '%') 


    AND a.skuId = #{skuId}


    AND a.spuId = #{spuId}


    AND a.treasurePrice = #{treasurePrice}


    AND a.treasureSumNum = #{treasureSumNum}


    AND a.treasureRobotNum = #{treasureRobotNum}


    AND a.treasureSumRound = #{treasureSumRound}


    AND a.treasureStartTime = #{treasureStartTime}


    AND a.treasureEndTime = #{treasureEndTime}


    AND a.status = #{status}


    AND a.actCurrentRound = #{actCurrentRound}


    AND a.actCurrentPurchasedNum = #{actCurrentPurchasedNum}


    AND a.actCurrentAccountNum = #{actCurrentAccountNum}

order by  a.createTime desc
